export const PASS_NPCS={
 'pass-stonecutter':{name:'Stonecutter Gilbert de Clare',text:['The old river road lies under a cliff fall. The masons’ track is the through-road now: foothills, lower adit, upper galleries, then Windscar Pass. Keep following the white-edged stone.','The quarry fed both towns before the war. First Light bought the road iron; Dawn Bloom took the stone for the city walls. When the hauling crews left, neither side paid to clear the lower road.']},
 'pass-guiding-cord':{name:'Caravan guide Zaynab bint Salim',text:['The galleries climb back towards daylight. Follow the worn stairs east for Windscar Pass. The northern opening in the lower adit leads to Crystal Hollow, a dead end; its stones are valuable, but it is not a way to Cybressa.','The army would rather pay an escort than a road crew. Every cart that loses a wheel up here carries less grain down to the market. That is how a broken road empties a kitchen.']},
 'pass-summit-porter':{name:'Porter Hugh de Bohun',text:['These cairns mark the optional summit trail. The way to Cybressa is below us: return to Windscar Pass, take its eastern exit, then descend the scree to Market Approach.','I carried stone for the first signal post. Now each company paints its own colours on it, but nobody replaces the ropes. A banner does not help much when a pack slips off the ledge.']}
};
export const PASS_RECORDS={
 passFoothills:{title:'The Road Above the Fallen Causeway',source:'An entry in the masons’ route book',text:'The low river road once carried stone from these hills to Philomere and grain back from Cybressa. Quarry families kept a separate climbing track so workers could reach the galleries when floodwater covered the banks. Its narrow turns were made for pack animals rather than wagons.\n\nThe war took the hauling crews and their repair tools. A cliff fall buried the lower road, and no company accepted the cost of reopening it. Travellers now use the masons’ track, where burrowing Ground Abyssals shelter in the loose soil and Rock Abyssals graze among the limestone ledges.\n\nFollow the worn track east into the Lower Adit. The route descends into the mountain before climbing through the Ascending Galleries to Windscar Pass. The river route is no longer a shortcut to the market; take supplies before leaving the plain.'},
 passLowerTunnel:{title:'Why the Adit Goes Down First',source:'From the quarry foreman’s survey notes',text:'The lower adit was dug to reach a seam beneath the limestone ridge. Its first galleries descend because the workable stone lay below the surface road. A second set of galleries later climbed through the ridge to an eastern working face. Together they provided a sheltered route through the mountain.\n\nWhen wartime hauling stopped, the timber crews left their cuttings behind. Burrowing Abyssals moved into the loose gravel, while bats followed insects through the air shafts. Crystal-bearing stones attract different animals from those seen on the riverbank outside. The worn pale floor marks the maintained walking route; rough gravel is wild habitat.\n\nContinue east towards the Ascending Galleries to regain height. A northern opening leads to Crystal Hollow and returns here; it does not reach Cybressa. The old rope marks identify that detour so a traveller is not led into a dead end while looking for the pass.'},
 passUpperTunnel:{title:'The Galleries That Climb Through the Ridge',source:'A porter’s copy of the quarry survey',text:'These galleries once joined the lower workings to the high eastern quarry. Stone was lowered in baskets, while porters climbed beside the haulage steps. The steps remain even where the lifting frames have rusted away, creating a route that rises through the mountain rather than ending beneath it.\n\nMilitary buyers requisitioned the good chains and left the broken ones hanging. Without regular hauling, mineral dust settled over the side chambers. Rock and Ground Abyssals moved in, while scavenging Steel types gathered around old fittings. The deeper shadowed gravel holds a different population after nightfall.\n\nFollow the pale stairs and the eastern gallery to daylight at Windscar Pass; the eastern scree beyond it descends towards Cybressa. The entrance behind you returns to the Lower Adit. Neither route requires a key or a military permit. The mountain is the obstacle here: keep your partners ready for wild encounters and leave the loose mineral beds if they need a safer path.'},
 passRidge:{title:'Windscar, the Exposed Crossing',source:'From the ridge watch’s route ledger',text:'Windscar is the saddle between the western quarry and the slope above Cybressa. The mountain shelters the river plain, but wind crosses this narrow ridge without a break. Low scrub grows between the limestone shelves; birds ride the updrafts, and cold-adapted Abyssals descend from the higher cairns to feed.\n\nThe watch once kept ropes and lamps for stone caravans. Both armies later used the height to observe the river. Their signal posts changed hands repeatedly, while the ropes and steps received less care. The pass now carries ordinary travellers because the lower causeway has collapsed.\n\nThe through-route goes east to Eastern Scree and then Market Approach. The north trail climbs to the Summit Cairns and returns here. The tunnel entrance to the west descends through the Ascending Galleries. Read the directions before choosing a trail: the summit gives a view of the road, but no shorter way down to the city.'},
 passEastSlope:{title:'Where the Mountain Reaches the Market',source:'A caravan wheelwright’s account',text:'The eastern slope sheds broken limestone towards the market road. Before the war, wheelwrights maintained retaining banks and a zigzag track so loaded carts could descend without sliding straight towards the river. Lichen grew on the older stones, and small Ground Abyssals nested beneath the warm banks.\n\nArmies took the repair timber and drove heavy wagons across the shelves. When the hauling crews withdrew, loose scree began covering the straight road. Pack traffic now follows the surviving bends. Rock and Ground species favour the exposed rubble; birds hunt above it by day, while ghostly scavengers move among the abandoned banks at night.\n\nKeep to the winding eastward path to reach Market Approach and Cybressa. West leads back up to Windscar Pass. Supplies left near the old escort post can help with the descent, but they are a single abandoned cache rather than a permanent shop or healing station.'},
 passCrystalPocket:{title:'The Chamber the Surveyors Left Closed',source:'From an abandoned mineral inventory',text:'Crystal Hollow was a side working, reached from the Lower Adit. Surveyors found crystals and metallic nodules here, but the seam narrowed before reaching the far side of the ridge. Its map ends at a mineral shelf rather than another entrance.\n\nThe quarry owners stopped paying for the survey once wartime contracts shifted to bulk stone. Their abandoned fittings and loose mineral beds now support Abyssals rarely seen on the open slopes. Fairy and Ghost types gather around bright crystals, while metal-feeding animals search the old equipment. This is a separate habitat, not simply a darker part of the same river road.\n\nDawn Bloom scholar Safiyya bint Yusuf has reopened the fossil survey on the far shelf. Speak to her at the workbench to investigate three exposed beds and choose one ancient Abyssal to revive. There is also a forgotten survey cache. Afterwards, return by the western opening to the Lower Adit. To reach Cybressa, continue east from that adit through the Ascending Galleries. There is no onward tunnel from this hollow.'},
 passSummit:{title:'The Cairns Above the Trade Road',source:'Notes left by the ridge porters',text:'Porters built these cairns above Windscar Pass to find their way in mist. Each pile of stone marked a safe stopping place rather than a military boundary. From the highest shelf, a traveller could see river traffic arriving from Philomere and market smoke above Cybressa.\n\nThe war turned that view into a watch post. Signal crews climbed here, but pack traffic stayed on the lower pass. Once the crews left, cold-loving Abyssals reclaimed the quiet shelves. Flying species use the updrafts, while Ice types rest among the shaded drifts and rock hollows. Their presence is why the summit’s sightings differ from the warmer foothills.\n\nThis is an optional climb with a porter’s supply cache near the far cairn. Read the watch keeper’s tablet beside the western trail to begin the cairn restoration. The three marked cairns lead to the highest shelf, where the old records place Caelynx, the Ice/Fairy Watcher. The only exit returns west to Windscar Pass. From there, take the eastern road down through the scree to Cybressa. The view does not provide a shortcut across the cliffs.'}
};
export function mountainRoute(room){const r=PASS_ROUTES[room];if(!r)return null;const weights=[35,28,22,10,5];return {room,explorationTable:true,encounterPacing:true,area:{id:room,name:r.name,rate:'NORMAL'},tables:['DAY','NIGHT'].map(phase=>({id:room+'-'+phase,phase,slots:r[phase].map((id,i)=>{let min=r.min;while(min<=r.max&&legalForm(id,min)!==id)min++;if(min>r.max||!DATA.species.some(s=>s.id===id))throw Error('Illegal pass species '+id);return {species_id:id,min_level:min,max_level:r.max,weight:weights[i],rarity:i<3?'Common':i===3?'Uncommon':'Rare',authoredSlot:true};})}))};}
const gate=(id,label,x,y,to,arrival)=>({id,label,x,y,to,arrival,door:true});
export function branchTo(m,spot){const node=m.road.reduce((best,p)=>Math.abs(p[0]-spot.x)+Math.abs(p[1]-spot.y)<Math.abs(best[0]-spot.x)+Math.abs(best[1]-spot.y)?p:best,m.road[0]);m.sidePaths.push({points:[[...node],[spot.x,node[1]],[spot.x,spot.y]]});m.spots.push(spot);}
export function installMountainPass(maps){
 for(const [room,r]of Object.entries(PASS_ROUTES)){
  const underground=['lower','upper','crystal'].includes(r.kind),m=maps[room]={name:r.name,area:room,bloom:true,terrain:underground?'cave':'ridge',passKind:r.kind,passStage:PASS_SPINE.indexOf(room)+1,road:r.road.map(p=>[...p]),grass:r.grass.map(p=>[...p]),sidePaths:[],props:[],spots:[{id:'area-sign',label:'Read the mountain route record',x:6,y:20,routeSign:true}],gates:[]};
  registerBiome(room,underground?'limestone':['ridge','summit'].includes(r.kind)?'highland':'mountain');
  if(PASS_SPINE.includes(room)){const i=PASS_SPINE.indexOf(room);m.gates.push(gate(room+'-back','West · '+(maps[PASS_SPINE[i-1]]?.name||PASS_ROUTES[PASS_SPINE[i-1]]?.name),1,17,PASS_SPINE[i-1],[44,17,'left']),gate(room+'-forward','East · '+(PASS_ROUTES[PASS_SPINE[i+1]]?.name||'Market Approach'),46,17,PASS_SPINE[i+1],[3,17,'right']));}
 }
 Object.assign(maps.rivercause.gates.find(g=>g.id==='rivercause-forward'),{label:'Limestone Foothills · mountain crossing',to:'passFoothills'});
 Object.assign(maps.rivercause2.gates.find(g=>g.id==='rivercause2-back'),{label:'Eastern Scree · mountain crossing',to:'passEastSlope'});
 const adit=maps.passLowerTunnel;adit.sidePaths.push({gateId:'pass-crystal-entry',points:[[25,10],[17,10],[17,5]]});adit.gates.push(gate('pass-crystal-entry','Optional · Crystal Hollow',17,5,'passCrystalPocket',[3,17,'right']));maps.passCrystalPocket.gates=[gate('pass-crystal-back','Return to Lower Adit',1,17,'passLowerTunnel',[17,7,'down'])];
 const ridge=maps.passRidge;ridge.sidePaths.push({gateId:'pass-summit-entry',points:[[19,8],[25,8],[25,4]]});ridge.gates.push(gate('pass-summit-entry','Optional · Summit Cairns',25,4,'passSummit',[3,17,'right']));maps.passSummit.gates=[gate('pass-summit-back','Return to Windscar Pass',1,17,'passRidge',[25,6,'down'])];
 for(const [room,id,x,y]of [['passFoothills','pass-stonecutter',14,23],['passUpperTunnel','pass-guiding-cord',27,22],['passSummit','pass-summit-porter',33,10]])branchTo(maps[room],{id,label:PASS_NPCS[id].name,x,y,sprite:'bystander'});
 installMountainQuests(maps,branchTo);
 for(const [room,id,x,y,label]of [['passLowerTunnel','pass-adit-cache',36,24,'Abandoned miners’ supplies'],['passCrystalPocket','pass-crystal-cache',39,14,'Surveyor’s mineral charm'],['passSummit','pass-summit-cache',39,17,'Porter’s summit chest'],['passEastSlope','pass-scree-cache',39,24,'Old escort provisions']])branchTo(maps[room],{id,label,x,y});
}
export function passObjective(room){const r=PASS_ROUTES[room];if(!r)return null;return {spot:PASS_SPINE.includes(room)?room+'-forward':room==='passSummit'?'pass-summit-back':'pass-crystal-back',text:PASS_SPINE.includes(room)?'Mountain crossing '+(PASS_SPINE.indexOf(room)+1)+'/7 · '+(room==='passEastSlope'?'Descend east to Market Approach':room==='passUpperTunnel'?'Climb east to Windscar Pass':room==='passLowerTunnel'?'Follow the eastern gallery uphill':'Follow the eastward through-route to Cybressa'):'Optional '+(room==='passSummit'?'summit':'crystal cavern')+' · return west to the crossing'};}
export function passRecordHTML(room,escape){const r=PASS_RECORDS[room];return r?'<article class="site-record"><p class="record-source">'+escape(r.source)+'</p><h3>'+escape(r.title)+'</h3>'+r.text.split('\n\n').map(p=>'<p>'+escape(p)+'</p>').join('')+'</article><p><b>Directions:</b> '+escape(passObjective(room).text)+'. Worn paths are safe; rough gravel and alpine scrub contain wild Abyssals.</p><hr>':'';}
export function drawPassTile(c,m,x,y,{road,walk,grass},asset){if(!m.passKind)return false;const cave=['lower','upper','crystal'].includes(m.passKind),high=['ridge','summit'].includes(m.passKind);
 if(!walk){if(high){const far=8+Math.sin(x*.24)*3,near=17+Math.sin(x*.18+1.6)*4;c.fillStyle=y<far?'#91b2bf':y<near?'#708c9a':'#526e7b';c.fillRect(x*16,y*16,16,16);if(y>=near){c.fillStyle='#45636c';c.fillRect(x*16+((x*7)%11),y*16+((y*3)%9),3,2);}}else{asset(c,mountainTileName(m.area,'wall'),x,y);c.save();c.fillStyle=cave?'#182b42':'#85969f';c.globalAlpha=cave?.24:.15;c.fillRect(x*16,y*16,16,16);c.restore();}}
 else asset(c,mountainTileName(m.area,road?'path':grass?'encounter':'ground'),x,y);
 return true;}

export function drawPassDetails(c,m,asset,walkable){if(!m.passKind)return;c.save();const cave=['lower','upper','crystal'].includes(m.passKind),high=['ridge','summit'].includes(m.passKind);
 // Cliff shadows follow blocked cells; the visible ledges use the collision geometry.
 c.fillStyle=cave?'#11182b66':'#131b2344';for(let y=2;y<29;y++)for(let x=2;x<46;x++)if(!walkable(x,y)&&walkable(x,y+1))c.fillRect(x*16,y*16+11,16,5);
 if(high){for(let y=2;y<29;y++)for(let x=2;x<46;x++)if(walkable(x,y)&&!walkable(x,y+1)){for(let drop=1;drop<=2;drop++){if(y+drop>30||walkable(x,y+drop))break;asset(c,mountainTileName(m.area,'wall'),x,y+drop);c.fillStyle=drop===1?'#73828a':'#586a75';c.fillRect(x*16,(y+drop)*16,16,2);c.fillStyle='#283e4a66';c.fillRect(x*16+((x*5)%9),(y+drop)*16+4,2,12);}}}
 if(high){c.strokeStyle='#dfe7e955';c.lineWidth=1;for(let i=0;i<9;i++){const x=(i*89+35)%730,y=(i*53+21)%460;c.beginPath();c.moveTo(x,y);c.lineTo(x+24,y-5);c.stroke();}}

 for(const g of m.gates){if(g.x!==1&&g.x!==46)continue;const x=g.x===1?3:42,y=17;c.fillStyle='#172533e8';c.fillRect(x*16-10,y*16-23,78,15);c.fillStyle='#f4e1af';c.font='bold 9px sans-serif';c.fillText(g.x===1?(m.passKind==='upper'?'↓ LOWER':m.passKind==='ridge'?'↓ TUNNEL':'← RETURN'):m.passKind==='foothill'?'↓ ADIT':m.passKind==='lower'?'CLIMB →':m.passKind==='upper'?'DAYLIGHT →':m.passKind==='scree'?'MARKET →':'EAST →',x*16-5,y*16-12);}
 c.restore();}
